      { q: 'Что выведет программа?', code: 'print(bool(-1))', options: ['True', 'False', '-1', 'ошибка'], check: 'output', explain: 'Любое ненулевое число, даже отрицательное, — истина.' },
      { q: 'Что выведет программа?', code: 'x = 10\nprint(x > 5 and x < 20 and x != 15)', options: ['True', 'False', '10', 'ошибка'], check: 'output', explain: 'Все три части истинны.' },
      { q: 'Что выведет программа?', code: 'age = 12\nticket = True\nif age >= 14 and ticket:\n    print("проход")\nelif age < 14 and ticket:\n    print("со взрослым")\nelse:\n    print("купи билет")', options: ['со взрослым', 'проход', 'купи билет', 'ничего'], check: 'output', explain: 'Первое условие ложно (12 < 14), второе истинно.' },
      { q: 'Что выведет программа?', code: 'x = 0\nif not x:\n    print("пусто")\nelse:\n    print("есть")', options: ['пусто', 'есть', 'ошибка', '0'], check: 'output', explain: 'x = 0 — ложь, not x — истина.' }
